"""Generate the storyboard and frame timeline from measured audio + authored cues."""
import json
import math
import re
import sys
import wave
from pathlib import Path

sys.stdout.reconfigure(encoding="utf-8")
PROJECT = Path(__file__).resolve().parents[1]
PLANS = PROJECT / "plans"
ANALYSIS = PROJECT / "analysis"
FPS = 30
meta = json.loads((ANALYSIS / "audio-timing.json").read_text(encoding="utf-8"))
reference = json.loads((ANALYSIS / "script-voiceover.json").read_text(encoding="utf-8"))
specs = json.loads((PLANS / "scene-specs.json").read_text(encoding="utf-8"))
sources = {i + 1: source for i, source in enumerate(meta["sources"])}
scenes = []
for i, spec in enumerate(specs):
    source = sources[spec["source"]]
    source_end = source["duration"] if spec["to"] is None else spec["to"]
    start = source["cumulativeStart"] + spec["from"]
    end = source["cumulativeStart"] + source_end
    start_frame = round(start * FPS)
    end_frame = math.ceil(end * FPS) if i == len(specs) - 1 else round(end * FPS)
    events = []
    for local, phrase, action, lead in spec["events"]:
        anchor = source["cumulativeStart"] + local
        anchor_frame = round(anchor * FPS)
        event_frame = max(start_frame, anchor_frame - lead)
        assert start_frame <= event_frame < end_frame, (spec["title"], event_frame)
        events.append({"atFrame": event_frame, "atSec": round(event_frame / FPS, 9), "localFrame": event_frame - start_frame, "voiceAnchorSec": round(anchor, 9), "voiceAnchorFrame": anchor_frame, "leadFramesApplied": anchor_frame - event_frame, "anchorText": phrase, "sourceLocalSec": local, "action": action, "timingStatus": "PROVISIONAL_ASR_ANCHOR_REVIEW_BY_EAR"})
    scene = {"id": i + 1, "title": spec["title"], "startSec": round(start_frame / FPS, 9), "endSec": round(end_frame / FPS, 9), "startFrame": start_frame, "endFrame": end_frame, "voiceover": " ".join(reference[n - 1] for n in spec["script"]), "voiceoverIsScriptReference": True, "recordedAudioIsAuthoritative": True, "scriptBeatIds": spec["script"], "component": spec["component"], "props": {"persistentPhoneId": "older-phone", "representation": spec["representation"], "events": events}, "onScreenText": spec["text"], "sfx": [], "sfxDirection": spec["sfx"], "tool": "remotion", "role": spec["role"], "effort": spec["effort"], "audioReference": {"source": "../inputs/" + source["file"], "sourceStartSec": spec["from"], "sourceEndSec": source_end, "unroundedTimelineStartSec": start, "unroundedTimelineEndSec": end, "boundaryStatus": "MEASURED_FILE_EDGE" if spec["from"] == 0 and spec["to"] is None else "INTERNAL_BOUNDARY_PROVISIONAL_ASR"}}
    scenes.append(scene)
total_frames = scenes[-1]["endFrame"]
timeline = {"fps": FPS, "width": 1080, "height": 1920, "timing": "MEASURED", "cueTiming": "PROVISIONAL_ASR_ANCHORS_REVIEW_BY_EAR", "durationInFrames": total_frames, "durationSec": total_frames / FPS, "audioDurationSec": meta["duration"], "pictureTailSec": total_frames / FPS - meta["duration"], "frameIntervals": "Half-open: startFrame included, endFrame excluded.", "audio": {"path": "../analysis/narration.wav", "pathsRelativeTo": "timeline JSON file", "sampleRate": 48000, "totalSamples": meta["totalSamples"], "sourceOrder": meta["order"], "sources": meta["sources"], "assembly": "Decoded and resampled sample-contiguous, numeric clip order, all words/pauses retained. Use ONE audio track at t=0; do not independently frame-round source clips."}, "style": "style.md", "captions": {"mode": "short_keywords_only", "fullNarrationCaptions": False, "arabicDirection": "rtl", "safeZone": {"left": 90, "right": 900, "top": 270, "bottom": 1420}}, "omittedScriptBeatIds": [13], "omissionNote": "Script beat 13 is not detected in the supplied recording. The script remains intact; do not add a synthetic voice, new silence, or a fabricated spoken ending.", "scenes": scenes}
(PLANS / "phone-slowdown-on-purpose-timeline.json").write_text(json.dumps(timeline, ensure_ascii=False, indent=2), encoding="utf-8")

event_frames = sorted(set([s["startFrame"] for s in scenes] + [e["atFrame"] for s in scenes for e in s["props"]["events"]] + [total_frames]))
max_gap = max(b - a for a, b in zip(event_frames, event_frames[1:])) / FPS
bins = []
for start_bin in range(0, total_frames, 300):
    count = sum(start_bin <= f < min(start_bin + 300, total_frames) for f in event_frames[:-1])
    bins.append({"startSec": start_bin / FPS, "endSec": min(start_bin + 300, total_frames) / FPS, "meaningfulChanges": count})

def span(scene):
    return f"{scene['startSec']:.3f}–{scene['endSec']:.3f}"

lines = ["# Plan: تليفونك ثقال… ولا ثقّلوه؟", "", "- Promise: Understand why an older phone can slow down, and why reduced performance alone does not establish a motive to force a new purchase.", f"- Audience: general | Length: {meta['duration']:.6f}s audio / {total_frames / FPS:.6f}s picture | Timing: MEASURED", "- Visual spine: One recognizable older phone with a diagnostic drawer. Each explanation opens a different module of the same phone, so the viewer keeps one mental model.", "- Hardest idea: Stored charge is different from deliverable peak power → keep the battery partly charged while its separate supply gauge cannot meet demand; then slow processor work until demand fits. Scenes 5–7 receive about 29 seconds for this mechanism.", "- Style: Reuse the shared [visual-system foundations](../../../plans/style.md), with the existing brief's light canvas/blue emphasis documented in the project-local [style.md](style.md). Illustrated 2D, Noto Sans Arabic, short headings, stable camera. Runtime.tech branding.", "", "**Timing authority.** ffprobe inspected all ten files; durations were verified by counting decoded 48 kHz samples. Source order is audio1 through audio10, never lexical order. The complete recording contains " + str(meta['totalSamples']) + f" samples. The final picture ends at frame {total_frames}, adding only {timeline['pictureTailSec']:.6f}s of picture after the audio. Use `../analysis/narration.wav` as one track from frame 0; preserve all existing pauses and words. Do not round each clip's placement independently.", "", "**Cue status.** File-edge durations are measured. Internal scene splits (audio5 at 8.76s and audio10 at 5.40s), word emphasis and individual visual cues are PROVISIONAL, located with local Whisper. Check these timestamps by ear before animation/render. Automatic Darija recognition is not trusted as new script copy. Voiceover cells below quote the approved script as reference; the supplied recording remains the timing and wording authority, including the shortened last clip. The unrecorded scripted closing is listed under Script feedback.", "", "**Concept chain, in order**", "1. The missed camera shot and a new-model ad create suspicion — story / comparison.", "2. Apple's 2017 acknowledgment and the disclosure controversy make the question real — story / sequence.", "3. An aging battery can retain charge but fail to deliver peak power — invisible process / comparison.", "4. Performance management reduces demand to avoid shutdown — invisible process / cause and effect.", "5. Apps, near-full storage and heat are additional explanations — structure / comparison.", "6. Establish the mechanism, keep motive separate, and check the actual cause before replacement — abstract concept / advice.", "", "## Cover frame", "Use the persistent older phone at x≈495/y≈840 with the camera spinner and one yellow question mark. Headline: **ثقال… ولا ثقّلوه؟** at y=310–450, 88 px Noto Sans Arabic. A small, neutral new-model ad may sit behind the phone, but no Apple logo plus villain stamp. The phone must remain recognizable at grid-thumbnail size. Separate future cover export; never insert a static cover before the hook.", "", "## Storyboard", "All scene spans are on the measured, frame-quantized picture timeline. Cue times already include the planned lead where appropriate; do not subtract 0.3 seconds again. Reveal dates and conclusions on their spoken anchors. Effort tags are planning estimates: S <30 min, M about 1–2 h, L half a day or more.", "", "| # | In-Out (s) | Voiceover (Darija) | Representation (what and why) | Motion and build steps | On-screen text | SFX / music | Tool | Role |", "|---|------------|--------------------|-------------------------------|------------------------|----------------|-------------|------|------|"]
for scene in scenes:
    motion = "**" + scene["effort"] + "**. " + " ".join(f"**{e['atSec']:.2f}s**: {e['action']}" for e in scene["props"]["events"])
    lines.append(f"| {scene['id']} | {span(scene)} MEASURED | {scene['voiceover']} | {scene['props']['representation']} | {motion} | {scene['onScreenText']} | {scene['sfxDirection']} Music off by default. | Remotion | {scene['role']} |")

recap_start = sources[9]["cumulativeStart"] + 6.9
recap_end = scenes[9]["endSec"]
lines += ["", "**Voice sync and audio design**", "- Decorative lead is not permission to reveal answers early: introduce phone/context immediately, prepare objects 9 frames ahead only after the line sets them up, and hit the actual term on its provisional voice anchor. Cue JSON records `voiceAnchorFrame` and `leadFramesApplied` explicitly.", "- Keep the existing pauses before الحل؟ and the Apple/date turn. Do not insert new 0.3–0.6s gaps or compress narration. Cue hits may be refined after listening without changing any recording.", "- Full narration subtitles are off. Short Arabic headings and diagnostic labels are animated in Remotion with RTL and isolated Latin terms; minimum label size 48 px, phrase size 64 px. Test `Apple اعترفت في 2017` and `حالة بطارية iPhone` for correct bidirectional layout.", "- Music is optional and omitted in the default plan. If later supplied, document its license and place it approximately 18–22 dB below narration, with extra ducking under the hook and Apple reveal. Sparse synthesized UI clicks only; `sfx` arrays remain empty until actual assets are selected.", "", "## Engagement map", "- Hook (0–2s): camera tap/stall from the first frame; first word ثقال freezes the preview, then ثقّلوه adds a question. No black frame or brand intro. The existing hook clip runs 3.392s; preserve its pause.", "- Open loops: the missed photo asks why this same phone changed; the new-model ad suggests a purchase motive with a question mark, not a verdict. The disclosure question is answered separately from the power mechanism.", "- Re-hooks: new-phone suspicion near 16s; the 2017 turn near 20s; why prevent shutdown near 38s; battery delivery challenge near 43s; الحل؟ near 56s; other causes near 63s; mechanism-versus-motive payoff near 93s.", f"- Save frame: the four familiar cause cards settle approximately {recap_start:.2f}–{recap_end:.2f}s, held for {recap_end - recap_start:.2f}s before the payoff. A second battery/storage check frame stays legible near 103.5–105.6s while the final practical line lands. No added spoken save request.", "- Comment prompt: keep the existing publishing-kit pinned question about phone model, age and where lag appears. No in-video CTA is added because the supplied ending has no room for a readable new question after the last line.", "- Share moment: a phone can be charged yet unable to supply a peak load; the same phone stays on after processor demand is reduced. A second useful moment is that replacing the battery can help if the battery is the cause.", "- Follow CTA: none in this cut. Let the publishing kit's next-video idea carry follow-up interest rather than adding an unrecorded outro.", "- Loop ending: during the recorded trailing silence, return the phone to the first camera/spinner geometry. No extra voice, end-card hold or appended silence.", "", "## Retention check", "- Meaningful changes per 10s (scene starts plus authored state changes, deduplicated by frame): " + "; ".join(f"{b['startSec']:.0f}–{b['endSec']:.1f}s: {b['meaningfulChanges']}" for b in bins) + ".", f"- Longest gap between authored meaningful changes: **{max_gap:.3f}s** (under 6s). Continuous spinner motion alone is not counted as extra events.", "- The recap deliberately holds the complete model for over two seconds; headings remain stable while the active diagnostic card receives a single emphasis. Do not introduce unrelated art to raise the cut count.", "- Muted test: camera misses a subject; partial battery charge and insufficient power visibly coexist; reduced processing visibly lowers demand; more app work queues; storage/heat visibly constrain performance; dotted purchase arrow remains uncertain.", "", "## Components and assets", "| Name | New / existing | Used in scenes | Effort |", "|------|----------------|----------------|--------|", "| Narration WAV + source manifest | Existing recordings, newly assembled analysis reference; original inputs unchanged | All | S |", "| Arabic/Latin fonts + OFL files | Existing reusable candidates in videos/vulhunter-skill/public/fonts; verify metadata and copy locally at build | All | S |", "| Arabic text/reveal/easing helpers | Existing candidates in videos/vulhunter-skill/src/design.tsx and videos/why-captcha-exists/production-stage/src/CaptchaVideo.tsx; adapt into this project, no cross-project mutation | All | S |", "| PhoneShell and tap/arrow primitives | Existing adaptation candidates: Device, Tap and Arrow in videos/selling-a-phone/production-v4/src-v4/SellingPhoneV4.tsx. They are local implementation helpers, not an import-ready package; extract only needed geometry, use this plan's safe-zone sizes and HTML Arabic | All | M |", "| CameraDelay + simple bird/photo prop | New reusable camera/latency module; original vector shapes | 1–2, 12 | M |", "| LaunchAd + HistoryDisclosure | New generic ad/history cards; Apple written as text, no external screenshots required | 3–4 | M |", "| PowerBudget + battery wear/charge/supply/demand states | New reusable explanatory system; gauges schematic with no invented values | 5–7, 11–12 | L |", "| TapFlowInset | New small analogy inset attached to the same phone; no separate visual world | 6 | M |", "| TaskQueue + working-memory tray | New, built from shared task-block primitives; RAM distinct from file storage | 7–9 | M |", "| DiagnosticDrawer + SummaryGrid | New reusable battery/storage/heat panels and recap grid | 10, 12 | M |", "| FactVsInference | New reusable solid/dotted relationship comparison | 3, 11 | M |", "| Optional UI SFX | Not selected; synthesize locally or document a licensed asset at build | Selected transitions only | S |", "", "## Build order", "1. Listen through the assembled WAV with the script alignment table. Correct provisional anchors, confirm the two internal boundaries and the shortened final clip. Keep the original words/pauses; use one Audio track.", "2. Set up 1080×1920/30 fps, local fonts, RTL test frames, safe-zone overlay and the short-heading track. Full narration captions remain off.", "3. Build and review the hook first: a frame-1 still, the ثقّلوه? emphasis frame and a 0–13.57s portrait preview. Check that the missed photo is readable and the older phone looks identical in the flashback.", "4. Build the central battery/power payoff (scenes 5–7) and the distinction/advice ending (11–12). Verify that charge is never mistaken for peak delivery and that the dotted motive arrow stays uncertain.", "5. Build history/disclosure, app workload, optimization counterexample, storage and heat using the same phone and primitives. Populate the progressively introduced recap grid.", "6. Review representative portrait frames for hook, 2017, charged-but-power-limited battery, reduced processor demand, memory-versus-storage, recap and motive distinction. Then render a short middle preview before any full export.", "7. Only after visual review, add optional quiet original/cleared SFX, render the full video and verify format, 30 fps, duration, complete narration in order, safe zones and loop ending. Save review images, MP4 and a project-specific production note in this project's output folder.", "", "## MVP fallback", "- Reuse one phone shell throughout; replace transitions with panel swaps on breath boundaries.", "- Use one static bird illustration moving out of frame instead of character animation. Keep the actual failed camera state and missed opportunity.", "- For history, two simple text cards are sufficient; no news montage or external footage.", "- For battery explanation, a static battery plus supply/demand bar with highlights is enough. The charge/power distinction and reduction of demand must remain visible. The spoken tap analogy still needs a small diagram, even in MVP.", "- Use three reusable feature blocks for workload and two distinct trays for RAM versus storage; no complex fluid simulation or realistic circuitry.", "- Skip all music and optional sound effects. Keep the four-cause summary and fact-versus-inference payoff.", "", "## Script feedback", "- No narration text was rewritten. At the user's request, the script's Visual / animation column and standalone visual-language paragraph were removed; the approved 13 spoken beats remain byte-for-byte unchanged as strings. The Time column is explicitly labeled an original estimate so the 120s draft cannot be mistaken for measured timing.", "- Recording duration is 106.154667s, not the original 120s target. The plan follows the supplied recordings without time stretching, silent padding or inferred extra takes.", "- Audio8 appears to paraphrase the update-improvement sentence (draft ASR hears تحديثات فعلا تزيد الأداء). Meaning is compatible with the original script; keep the recording, show an optimization counterexample and check the exact words by ear.", "- Audio10 compresses script beats 11–12 into one take. Its draft is consistent with: intentional slowdown can happen in some cases; slowdown alone does not prove a purchase motive; check battery/storage; battery replacement can help when that is the cause. It does not audibly align word-for-word with the longer written version. Match the recorded clauses; do not animate the omitted sentences as if spoken.", "- Script beat 13 (ماشي كل تليفون ثقال… معناها ثقّلوه باش تبدّلو.) is not detected in the supplied audio, which ends after the battery-replacement/savings advice. Leave that script line intact as an optional unrecorded ending. The current plan uses a visual loop in the existing trailing silence instead of inventing a voiceover.", "- Opening audio contains small conversational additions compared with the script. ASR is unreliable on Darija: the approved script remains the reference, and `analysis/transcripts` is boundary evidence only. Check every cue by ear before final animation.", "", "## Risks", "- Timing risk: measured clip lengths do not make word cues forced-aligned. Both internal splits and all word hits remain provisional until listening. JSON exposes that distinction.", "- Meaning risk: intentional performance control is not proof of a sales motive. Separate the solid technical mechanism from the dotted purchase inference; penalties/settlements relate to disclosure, not a general proof about all phones.", "- Technical-accuracy risk: battery charge, age and deliverable peak power are distinct. Water is a short analogy for delivery rate; do not imply a literal tap, a universal threshold, or a battery-health percentage that predicts exact speed.", "- App/thermal risk: not every update increases load; show the optimization counterexample. RAM/working memory and file storage need different labeled trays. Heat can reduce performance even with a healthy battery.", "- Layout risk: Arabic shaping/bidi and phone UI labels must be tested at portrait scale. Remotion handles all text; no Arabic text in Manim or raw SVG text. Never shrink key labels under 48 px.", "- Asset risk: optional SFX/music remain unselected and unused until original or documented licensed assets exist. Use original vector phone/ad props rather than depending on licensed screenshots.", "- Scope: this delivery is the script cleanup, audio inspection, storyboard and timeline. No finished video, preview or rendered cover is claimed."]
(PLANS / "phone-slowdown-on-purpose-plan.md").write_text("\n".join(lines) + "\n", encoding="utf-8")

alignment = []
for beat, text in enumerate(reference, 1):
    matching = [s for s in scenes if beat in s["scriptBeatIds"]]
    alignment.append({"scriptBeat": beat, "voiceover": text, "sceneIds": [s["id"] for s in matching], "startSec": matching[0]["audioReference"]["unroundedTimelineStartSec"] if matching else None, "endSec": matching[-1]["audioReference"]["unroundedTimelineEndSec"] if matching else None, "status": "NO_MATCH_DETECTED_NOT_SCHEDULED" if not matching else "CONDENSED_RECORDED_VERSION_CHECK_BY_EAR" if beat in (11, 12) else "SCRIPT_REFERENCE_ALIGNED_TO_CLIP_OR_PROVISIONAL_ASR_SPLIT"})
(ANALYSIS / "script-audio-alignment.json").write_text(json.dumps({"note": "Reference alignment, not a corrected transcript. Original narration stays authoritative; check word boundaries by ear.", "beats": alignment}, ensure_ascii=False, indent=2), encoding="utf-8")

report = {"audioDurationSec": meta["duration"], "pictureDurationSec": total_frames / FPS, "totalFrames": total_frames, "pictureTailSec": timeline["pictureTailSec"], "sceneCount": len(scenes), "noSceneGapsOrOverlaps": all(a["endFrame"] == b["startFrame"] for a, b in zip(scenes, scenes[1:])), "startsAtZero": scenes[0]["startFrame"] == 0, "coversAllAudio": total_frames / FPS >= meta["duration"], "secondsAndFramesAgree": all(abs(s[k + 'Sec'] * FPS - s[k + 'Frame']) < 1e-6 for s in scenes for k in ('start', 'end')), "originalVoiceoverPreserved": meta["scriptWordsPreserved"], "scriptBeatCount": len(reference), "scriptBeat13NotInRecording": True, "maxMeaningfulChangeGapSec": max_gap, "meaningfulChangesPer10Sec": bins, "cueStatus": "PROVISIONAL_NOT_LISTENED_BY_EAR", "fullNarrationCaptions": False, "allTenSourcesUsed": len(meta["sources"]) == 10}
with wave.open(str(ANALYSIS / "narration.wav"), "rb") as audio:
    report["assembledWavSamplesAgree"] = audio.getnframes() == meta["totalSamples"]
    report["assembledWavSampleRate"] = audio.getframerate()
script = (PROJECT / "scripts/phone-slowdown-on-purpose.md").read_text(encoding="utf-8")
report["scriptVisualDirectionsRemoved"] = "Visual / animation" not in script and "Visual language:" not in script
assert report["noSceneGapsOrOverlaps"] and report["startsAtZero"] and report["coversAllAudio"]
assert report["secondsAndFramesAgree"] and report["assembledWavSamplesAgree"] and report["scriptVisualDirectionsRemoved"]
assert report["originalVoiceoverPreserved"] and max_gap <= 6
(ANALYSIS / "plan-validation.json").write_text(json.dumps(report, ensure_ascii=False, indent=2), encoding="utf-8")

brief_path = PROJECT / "brief.md"
brief = brief_path.read_text(encoding="utf-8")
brief = brief.replace("- Status: planning; script delivered.", "- Status: planning; script cleaned, recorded narration inspected, storyboard and timeline delivered.")
brief = brief.replace("- Recording files: None supplied; creator records after script review.", "- Recording files: inputs/audio1.ogg through audio10.ogg, numeric order; all words and pauses retained. Measured total: 106.154667s (5,095,424 samples at 48 kHz).")
brief = brief.replace("- Script length: 292 spoken words, approximately 120 seconds.", "- Written script: 292 words, originally estimated at 120s. Recorded delivery: 106.154667s; shortened final clauses and the unrecorded closing are documented in plans/phone-slowdown-on-purpose-plan.md.")
brief = brief.replace("- Closing: “ماشي كل تليفون ثقال… معناها ثقّلوه باش تبدّلو.”", "- Optional scripted closing (not detected in the supplied recordings): “ماشي كل تليفون ثقال… معناها ثقّلوه باش تبدّلو.” Current picture ending loops to the camera during the recorded trailing silence.")
brief = brief.replace("- Narration: No supplied recording; preserve approved script order when recording/building.", "- Narration: Supplied audio1–audio10 in numeric order; no trimming, replacement, reordering or synthetic ending. The recorded delivery is authoritative.")
brief = brief.replace("- Timing: Script timings are estimates; animation must follow actual recording.", "- Timing: The script table retains original estimates; plans/phone-slowdown-on-purpose-timeline.json contains measured, frame-quantized scene spans and provisional ASR cue anchors to check by ear.")
brief = re.sub(r"- Script includes three hooks,[^\n]*", "- Script retains all 13 approved spoken beats; visual directions now live only in plans/. The storyboard uses 12 scenes covering the ten supplied recordings; beat 13 is left unrecorded and unscheduled.", brief)
brief = re.sub(r"- Checks: Spoken word count;[^\n]*", "- Checks: ffprobe metadata, decoded sample counts, assembled WAV length, unchanged script wording, timeline continuity, frame/second agreement, source order, caption policy and maximum meaningful-change gap. See analysis/plan-validation.json. Internal cues still require listening.", brief)
brief = brief.replace("- Storyboard/preview/export: Not requested or produced in this script task.", "- Storyboard and timeline: plans/phone-slowdown-on-purpose-plan.md and plans/phone-slowdown-on-purpose-timeline.json. Style: plans/style.md. Preview/export not requested or produced in this planning task.")
brief_path.write_text(brief, encoding="utf-8")
print(json.dumps({k: v for k, v in report.items() if k != "meaningfulChangesPer10Sec"}, ensure_ascii=False, indent=2))
print("SCENES")
for scene in scenes:
    print(f"{scene['id']:02} {span(scene)} {scene['title']}")
